-- TASK-0065 Open Hand teaching items: biology (6 items). Generated by
-- scripts/content-seed/task0065_load/build_load_sql.py. Idempotent: re-running
-- skips content_keys already present in the target pack.
do $oht0065$
declare
  v_subject text := 'biology';
  v_tsv uuid := 'c676d1fc-3b58-4896-89e3-852d9bd1f81b';
  v_owner uuid := (select p.user_id from app.profiles p where p.user_id = 'f5a26c6b-3566-4d58-9e97-979fbb947564');
  v_items jsonb := $oht0065json$[{"content_key":"APBIO-OHT-1.1","topic_code":"1.1","title":"Structure of Water and Hydrogen Bonding","stem":"A shallow pond and the sand beside it receive the same sunlight for an hour. The sand heats up by many degrees, but the pond water warms only slightly. Which statement best explains why the water changes temperature so little?","choices":[{"choice_key":"A","choice_text":"Water molecules are nonpolar, so they pass sunlight through without absorbing much of it and only a small fraction of the incoming heat is taken in by the pond.","is_correct":false,"rationale":"Tempting if you assume water heats slowly because sunlight passes through it, and that water molecules have no charged regions — but water is polar, and its small temperature change comes from the hydrogen bonds between its molecules. Fix: start from water's polarity and trace the chain: polarity, then hydrogen bonds, then energy absorbed as those bonds break."},{"choice_key":"B","choice_text":"Heat absorbed by the water is first used to break some of the many hydrogen bonds between polar water molecules, so less of it raises the molecules' motion and temperature.","is_correct":true,"rationale":"Water's polarity lets each molecule hydrogen-bond to its neighbors, and breaking those bonds absorbs energy. That is the high specific heat that keeps aquatic environments thermally stable."},{"choice_key":"C","choice_text":"Cohesion pulls the water molecules together at the surface, which blocks heat from entering the pond.","is_correct":false,"rationale":"Tempting if you reach for cohesion because it is the hydrogen-bond property you remember best — but cohesion explains surface tension, not why water resists temperature change. Fix: name the observation first (a small temperature change), then pick the property that matches it (high specific heat)."},{"choice_key":"D","choice_text":"Evaporation removes all of the absorbed heat immediately, so the pond cannot warm at all.","is_correct":false,"rationale":"Tempting if you know that evaporation cools water and stretch that into 'evaporation removes all the heat' — but the stem says the pond did warm slightly, so the heat was not all removed. Fix: check each choice against the data in the stem and reject any that contradicts the observed slight warming."}]},{"content_key":"APBIO-OHT-1.4","topic_code":"1.4","title":"Carbohydrates","stem":"A potato plant stores glucose in its tubers as starch, while its cell walls contain cellulose, also a polymer of glucose. Which statement best explains why these two carbohydrates serve different functions?","choices":[{"choice_key":"A","choice_text":"Cellulose is built from a different monosaccharide than starch, so the two polymers cannot share a monomer.","is_correct":false,"rationale":"Tempting if you assume that two molecules with different jobs must be built from different monomers — but the stem says both starch and cellulose are polymers of glucose. Fix: reread the stem for what the two molecules share, then look for a difference in how their subunits are linked."},{"choice_key":"B","choice_text":"Carbohydrates function only as energy sources, so cellulose must be used as stored fuel like starch for the whole plant, including the cell walls.","is_correct":false,"rationale":"Tempting if you remember carbohydrates only as fuel and assume every carbohydrate is stored energy — but cellulose in cell walls serves as structural support, not fuel. Fix: for each carbohydrate, ask where it is found in the plant and match its function to that location."},{"choice_key":"C","choice_text":"The same glucose subunits are joined in different arrangements, with branched, accessible starch suited to storage and linear cellulose suited to rigid support.","is_correct":true,"rationale":"Bond arrangement and branching pattern determine function even when the monomer is identical. Branched starch is readily broken down for energy, while linear cellulose forms rigid structural fibers."},{"choice_key":"D","choice_text":"Starch is a carbohydrate made by dehydration synthesis, while cellulose forms by hydrolysis, which gives it its different role.","is_correct":false,"rationale":"Tempting if you mix up dehydration synthesis and hydrolysis and think hydrolysis can build a polymer — but both starch and cellulose are built by dehydration synthesis, and hydrolysis breaks polymers apart. Fix: label each reaction before choosing: dehydration synthesis removes water to build a polymer, and hydrolysis adds water to break one."}]},{"content_key":"APBIO-OHT-1.7","topic_code":"1.7","title":"Proteins","stem":"A reducing chemical breaks the disulfide bridges between cysteine side chains in a single-chain enzyme. The amino acid sequence is unchanged, but the enzyme loses its activity. Which level of protein structure is directly altered?","choices":[{"choice_key":"A","choice_text":"Tertiary structure, because disulfide bridges between R groups help hold the polypeptide in its overall three-dimensional shape.","is_correct":true,"rationale":"Tertiary structure is the overall 3D shape held by R-group interactions, including disulfide bridges. Breaking them changes the shape of the active site while the sequence stays the same."},{"choice_key":"B","choice_text":"Primary structure, because breaking the bridges changes the order of amino acids so that the whole chain rearranges.","is_correct":false,"rationale":"Tempting if you reason that because the cysteines are part of the sequence, breaking their bridges must change the sequence — but the stem says the amino acid order is unchanged; only bonds between side chains broke. Fix: ask whether the order of amino acids changed, and if it did not, rule out primary structure."},{"choice_key":"C","choice_text":"Secondary structure, because disulfide bridges are the main bonds in alpha helices.","is_correct":false,"rationale":"Tempting if you assume that disulfide bridges, being strong covalent bonds, must be what holds alpha helices together — but helices and pleated sheets are held by hydrogen bonds between backbone atoms, while disulfide bridges link R groups. Fix: sort each bond by what it connects: backbone to backbone means secondary, R group to R group means tertiary."},{"choice_key":"D","choice_text":"Quaternary structure, because the bridges hold several polypeptide chains together.","is_correct":false,"rationale":"Tempting if you remember that disulfide bridges can link separate chains in some proteins and apply that here — but this enzyme is a single chain, so it has no quaternary structure. Fix: count the polypeptide chains described in the stem before choosing quaternary structure."}]},{"content_key":"APBIO-OHT-2.9","topic_code":"2.9","title":"Cell Compartmentalization","stem":"Lysosomes maintain an acidic interior and contain digestive enzymes. Which statement best explains the advantage of keeping these in a membrane-bound compartment?","choices":[{"choice_key":"A","choice_text":"The membrane isolates the acidic conditions and digestive enzymes, so they do not interfere with or damage reactions elsewhere in the cell.","is_correct":true,"rationale":"Compartmentalization lets a cell maintain conditions such as low pH and high enzyme concentration that would disrupt other reactions if free in the cytosol. Separation makes the process efficient and safer."},{"choice_key":"B","choice_text":"The membrane supplies extra ATP that makes the digestive enzymes work faster.","is_correct":false,"rationale":"Tempting if you link membranes with ATP production, as in mitochondria, and assume every membrane powers its compartment — but the lysosome membrane does not make ATP for its enzymes; its advantage here is separation. Fix: ask what the membrane keeps apart (acid and enzymes versus the cytosol) before choosing an energy explanation."},{"choice_key":"C","choice_text":"The membrane removes the need for any transport, since everything needed is already inside because the enzymes and acid are already contained inside.","is_correct":false,"rationale":"Tempting if you think 'enclosed' means 'sealed off', so a compartment needs no traffic in or out — but lysosomes must take in material to digest and move products out across their membrane. Fix: for any compartment, trace what has to cross its membrane in and out before accepting a 'no transport' claim."},{"choice_key":"D","choice_text":"Enzymes cannot function at all unless they are surrounded by a membrane.","is_correct":false,"rationale":"Tempting if you overgeneralize from enzymes that work inside organelles and conclude that every enzyme needs a membrane around it — but many enzymes, such as those of glycolysis, work freely in the cytosol. Fix: test any 'all' or 'cannot at all' claim by thinking of one counterexample."}]},{"content_key":"APBIO-OHT-3.2","topic_code":"3.2","title":"Environmental Impacts on Enzyme Function","stem":"An enzyme has an optimum pH of 7. At pH 2 its activity falls to nearly zero. When the pH is returned to 7, its activity returns. Which statement best explains these results?","choices":[{"choice_key":"A","choice_text":"The acid broke the peptide bonds, permanently destroying the amino acid sequence.","is_correct":false,"rationale":"Tempting if you confuse denaturation with digestion and assume acid breaks the peptide bonds of the chain — but broken peptide bonds would permanently destroy the sequence, and activity came back at pH 7. Fix: use the recovery at pH 7 as evidence and rule out any permanent change to the amino acid sequence."},{"choice_key":"B","choice_text":"The acid acted as a competitive inhibitor by binding permanently in the active site, and the pH change blocked substrate from fitting.","is_correct":false,"rationale":"Tempting if you treat any drop in activity as inhibition and picture H+ ions sitting in the active site — but no inhibitor was added, and a permanently bound inhibitor could not explain the recovery at pH 7. Fix: identify what the stem actually changed (only pH) and explain the result through the enzyme's shape, not an inhibitor."},{"choice_key":"C","choice_text":"The enzyme ran out of substrate at pH 2, and fresh substrate appeared at pH 7.","is_correct":false,"rationale":"Tempting if you explain every change in reaction rate by substrate amount, since substrate concentration does affect rate — but the stem changes only pH and says nothing about substrate. Fix: find the one variable the stem changes (pH) and choose an explanation built on that variable."},{"choice_key":"D","choice_text":"Low pH disrupted hydrogen bonds and other interactions that hold the enzyme's shape, changing the active site, and the shape was restored when conditions returned to normal.","is_correct":true,"rationale":"Outside its optimum range, changes in pH disrupt the interactions that maintain the 3D shape, which alters the active site. Because the denaturation was reversible, the enzyme refolded when pH returned to 7."}]},{"content_key":"APBIO-OHT-3.3","topic_code":"3.3","title":"Cellular Energy","stem":"The reaction glucose + phosphate to glucose-6-phosphate does not occur spontaneously. A cell couples it to ATP hydrolysis and the reaction proceeds. Why does coupling make the reaction possible?","choices":[{"choice_key":"A","choice_text":"The energy released by ATP hydrolysis is used to drive the energy-requiring reaction, so the combined process can proceed.","is_correct":true,"rationale":"Energy coupling links an energy-releasing reaction (ATP to ADP and phosphate) to one that needs energy input. The released energy drives the second reaction, which is how cells run processes that would not occur alone."},{"choice_key":"B","choice_text":"ATP acts as an enzyme that lowers the activation energy of the glucose reaction.","is_correct":false,"rationale":"Tempting if you confuse the two ways a reaction can be helped, lowering activation energy (what enzymes do) and supplying energy (what ATP does) — but ATP is not a catalyst; it is used up when it is hydrolyzed. Fix: ask whether the molecule is changed by the reaction, and if it is, as ATP is, do not call it an enzyme."},{"choice_key":"C","choice_text":"ATP stores its energy in a form that is later released as heat, which speeds the reaction in the cell and gives the reaction an extra push forward.","is_correct":false,"rationale":"Tempting if you think cells speed reactions by heating them, so ATP's energy must be released as heat — but heat cannot drive one specific energy-requiring reaction; coupling transfers ATP's phosphate and energy directly to glucose. Fix: trace where ATP's phosphate group goes (it ends up on glucose) to see energy transferred by coupling rather than lost as heat."},{"choice_key":"D","choice_text":"ATP is simply energy itself, so it adds a quantity of energy to the glucose.","is_correct":false,"rationale":"Tempting if you take 'energy currency' literally and treat ATP as pure energy rather than a molecule — but ATP is a molecule, and its hydrolysis to ADP and phosphate releases energy that is coupled to the glucose reaction. Fix: write ATP → ADP + phosphate next to the glucose reaction so you see a molecule reacting and its phosphate being transferred."}]}]$oht0065json$::jsonb;
  v_pv uuid; v_npv int;
  r jsonb; c jsonb;
  v_ci uuid; v_civ uuid; v_key text; v_correct text;
  v_loaded int := 0; v_skipped int := 0; v_released int := 0;
begin
  select count(*) into v_npv
  from app.exam_pack_versions epv join app.exam_packs ep on ep.id = epv.exam_pack_id
  join app.subjects s on s.id = ep.subject_id
  where s.subject_key = v_subject and epv.status = 'published' and epv.retired_at is null;
  if v_npv = 0 then
    raise exception 'task0065: no published, non-retired exam pack version for %', v_subject;
  end if;
  -- Prefer the published pack that already holds teaching items (two exist for
  -- Statistics in Development); otherwise require exactly one.
  select epv.id into v_pv
  from app.exam_pack_versions epv join app.exam_packs ep on ep.id = epv.exam_pack_id
  join app.subjects s on s.id = ep.subject_id
  where s.subject_key = v_subject and epv.status = 'published' and epv.retired_at is null
    and (v_npv = 1 or exists (select 1 from app.open_hand_teaching_items t
                              join app.content_items ci on ci.id = t.content_item_id
                              where ci.exam_pack_version_id = epv.id))
  order by (select count(*) from app.open_hand_teaching_items t join app.content_items ci on ci.id = t.content_item_id
            where ci.exam_pack_version_id = epv.id) desc, epv.id
  limit 1;
  if v_pv is null then
    raise exception 'task0065: % has % published packs and none holds teaching items; pick one explicitly', v_subject, v_npv;
  end if;

  for r in select * from jsonb_array_elements(v_items) loop
    v_key := r->>'content_key';
    if exists (select 1 from app.content_items where exam_pack_version_id = v_pv and content_key = v_key) then
      v_skipped := v_skipped + 1;
      continue;
    end if;
    if jsonb_array_length(r->'choices') <> 4
       or (select count(*) from jsonb_array_elements(r->'choices') x where (x->>'is_correct')::boolean) <> 1 then
      raise exception 'task0065: % must have 4 choices with exactly one correct', v_key;
    end if;
    if not exists (select 1 from app.taxonomy_topics tt where tt.taxonomy_source_version = v_tsv
                   and tt.topic_code = r->>'topic_code') then
      raise exception 'task0065: topic % not in taxonomy %', r->>'topic_code', v_tsv;
    end if;
    select x->>'choice_key' into v_correct from jsonb_array_elements(r->'choices') x
    where (x->>'is_correct')::boolean;

    insert into app.content_items (exam_pack_version_id, content_key, item_type, title, status)
    values (v_pv, v_key, 'mcq', r->>'title', 'draft')
    returning id into v_ci;

    insert into app.content_item_versions (content_item_id, version_num, stem, content_hash, status,
      review_status, rubric_type, evaluator_strategy, canonical_answer_1)
    values (v_ci, 1, r->>'stem', md5(v_key), 'draft', 'tutor_review_pending', 'mcq', 'rule_based_mcq', v_correct)
    returning id into v_civ;

    for c in select * from jsonb_array_elements(r->'choices') loop
      insert into app.mcq_choices (content_item_version_id, choice_key, choice_text, is_correct, rationale)
      values (v_civ, c->>'choice_key', c->>'choice_text', (c->>'is_correct')::boolean, c->>'rationale');
    end loop;

    insert into app.content_item_cells (content_item_version_id, content_item_id, taxonomy_source_version,
      topic_code, skill_code, is_primary, assignment_status, source, model_run_id)
    values (v_civ, v_ci, v_tsv, r->>'topic_code', null, true, 'authored', 'task0065_oht_generated_2026_10_06',
      'TASK-0065 Open Hand teaching batch 2026-10-06 (authored to this topic; checked per CHECK_RESULTS.md)');

    -- Publish gates: enforce_publish_gate (approved review_status),
    -- tg_content_pipeline_guard_publish (published only from reviewed_approved),
    -- enforce_mcq_stem_choice_sync (runs on publish; choices exist by now).
    update app.content_item_versions set status = 'reviewed_approved', review_status = 'question_review_approved',
      approved_by = v_owner, approved_at = now() where id = v_civ;
    update app.content_item_versions set status = 'published', published_at = now() where id = v_civ;
    update app.content_items set status = 'reviewed_approved' where id = v_ci;
    update app.content_items set status = 'published' where id = v_ci;

    insert into app.open_hand_teaching_items (content_item_id, topic_code, source, note)
    values (v_ci, r->>'topic_code', 'generated', 'TASK-0065 batch 2026-10-06')
    on conflict (content_item_id) do nothing;
    v_loaded := v_loaded + 1;
  end loop;

  -- Return superseded spares (same subject + topic) to scoring.
  with rel as (
    update app.open_hand_teaching_items t set released_at = now()
    from app.content_items ci, app.exam_pack_versions epv, app.exam_packs ep, app.subjects s
    where ci.id = t.content_item_id and epv.id = ci.exam_pack_version_id and ep.id = epv.exam_pack_id
      and s.id = ep.subject_id and s.subject_key = v_subject
      and t.source = 'spare' and t.released_at is null
      and exists (select 1 from app.open_hand_teaching_items g
                  join app.content_items gci on gci.id = g.content_item_id
                  where g.source = 'generated' and g.released_at is null and g.note = 'TASK-0065 batch 2026-10-06'
                    and g.topic_code = t.topic_code and gci.exam_pack_version_id = v_pv
                    and gci.status = 'published')
    returning t.content_item_id)
  select count(*) into v_released from rel;

  raise notice 'task0065 %: pack %, loaded %, skipped %, spares released %', v_subject, v_pv, v_loaded, v_skipped, v_released;
end
$oht0065$;
